begin;
create temporary table annual_test(k text primary key,v uuid);grant all on annual_test to authenticated;
create function pg_temp.ok(v boolean,label text) returns void language plpgsql as $$begin if v is distinct from true then raise exception 'FAIL: %',label;end if;end$$;
create function pg_temp.denied(s text) returns void language plpgsql as $$begin begin execute s;exception when insufficient_privilege or check_violation or raise_exception then return;end;raise exception 'FAIL: allowed';end$$;
insert into annual_test values('admin',gen_random_uuid()),('other',gen_random_uuid());
insert into auth.users(id,aud,role,email,email_confirmed_at,raw_user_meta_data) select v,'authenticated','authenticated',v||'@example.test',now(),'{}' from annual_test;
set local role authenticated;
select set_config('request.jwt.claim.sub',(select v::text from annual_test where k='admin'),true);
insert into annual_test values('school',public.create_school('연간 테스트','서울','중학교'));
