select pg_temp.ok((select count(*)=0 from public.annual_academic_plans where academic_year_id=(select v from annual_test where k='year')),'outsider cannot read');
select pg_temp.denied(format('select public.save_annual_plan(%L,%L,2,%L)',(select v from annual_test where k='school'),(select v from annual_test where k='year'),$doc${"vacations":[],"days":{},"holidays":{},"timetable":[{"grade":1,"weekday":1,"start":1,"end":6},{"grade":1,"weekday":2,"start":1,"end":6},{"grade":1,"weekday":3,"start":1,"end":6},{"grade":1,"weekday":4,"start":1,"end":6},{"grade":1,"weekday":5,"start":1,"end":6},{"grade":2,"weekday":1,"start":1,"end":6},{"grade":2,"weekday":2,"start":1,"end":6},{"grade":2,"weekday":3,"start":1,"end":6},{"grade":2,"weekday":4,"start":1,"end":6},{"grade":2,"weekday":5,"start":1,"end":6},{"grade":3,"weekday":1,"start":1,"end":6},{"grade":3,"weekday":2,"start":1,"end":6},{"grade":3,"weekday":3,"start":1,"end":6},{"grade":3,"weekday":4,"start":1,"end":6},{"grade":3,"weekday":5,"start":1,"end":6}],"recurring":[],"allocations":[],"business":[],"departments":["교무지원부","교육과정지원부","학생활동지원부","기숙사지원부","방과후학교지원부","행정실"],"weather":{"nx":60,"ny":127,"landCode":"11B00000","tempCode":"11B10101"}}$doc$));
